vector<long long> dijkstra(int n, vector<vector<pair<int,int>>>& adj, int src) {
    vector<long long> dist(n, LLONG_MAX);
    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
    dist[src] = 0; pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;            // stale entry
        for (auto [v, w] : adj[u])
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
    }
    return dist;
}

class Solution {
public:
    int networkDelayTime(vector<vector<int>>& times, int n, int k) {
        vector<vector<pair<int,int>>> adj(n + 1);
        for (auto& t : times) adj[t[0]].push_back({t[1], t[2]});
        vector<int> dist(n + 1, INT_MAX); dist[k] = 0;
        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;
        pq.push({0, k});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[u]) continue;
            for (auto& [v, w] : adj[u])
                if (d + w < dist[v]) { dist[v] = d + w; pq.push({dist[v], v}); }
        }
        int ans = 0;
        for (int i = 1; i <= n; i++) ans = max(ans, dist[i]);
        return ans == INT_MAX ? -1 : ans;
    }
};

import heapq
class Solution:
    def networkDelayTime(self, times, n, k):
        adj = [[] for _ in range(n + 1)]
        for u, v, w in times:
            adj[u].append((v, w))
        dist = {k: 0}
        pq = [(0, k)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist.get(u, float('inf')):
                continue
            for v, w in adj[u]:
                if d + w < dist.get(v, float('inf')):
                    dist[v] = d + w
                    heapq.heappush(pq, (dist[v], v))
        return max(dist.values()) if len(dist) == n else -1

class Solution {
public:
    int minimumEffortPath(vector<vector<int>>& h) {
        int R = h.size(), C = h[0].size();
        vector<vector<int>> eff(R, vector<int>(C, INT_MAX));
        priority_queue<tuple<int,int,int>, vector<tuple<int,int,int>>, greater<>> pq;
        pq.push({0, 0, 0}); eff[0][0] = 0;
        int dx[] = {0,0,1,-1}, dy[] = {1,-1,0,0};
        while (!pq.empty()) {
            auto [e, r, c] = pq.top(); pq.pop();
            if (r == R - 1 && c == C - 1) return e;
            if (e > eff[r][c]) continue;
            for (int d = 0; d < 4; d++) {
                int nr = r + dx[d], nc = c + dy[d];
                if (nr < 0 || nc < 0 || nr >= R || nc >= C) continue;
                int ne = max(e, abs(h[nr][nc] - h[r][c]));
                if (ne < eff[nr][nc]) { eff[nr][nc] = ne; pq.push({ne, nr, nc}); }
            }
        }
        return 0;
    }
};

import heapq
class Solution:
    def minimumEffortPath(self, h):
        R, C = len(h), len(h[0])
        eff = [[float('inf')] * C for _ in range(R)]
        eff[0][0] = 0
        pq = [(0, 0, 0)]
        while pq:
            e, r, c = heapq.heappop(pq)
            if r == R - 1 and c == C - 1:
                return e
            if e > eff[r][c]:
                continue
            for nr, nc in ((r,c+1),(r,c-1),(r+1,c),(r-1,c)):
                if 0 <= nr < R and 0 <= nc < C:
                    ne = max(e, abs(h[nr][nc] - h[r][c]))
                    if ne < eff[nr][nc]:
                        eff[nr][nc] = ne
                        heapq.heappush(pq, (ne, nr, nc))
        return 0

class Solution {
public:
    int findCheapestPrice(int n, vector<vector<int>>& flights, int src, int dst, int K) {
        vector<vector<pair<int,int>>> adj(n);
        for (auto& f : flights) adj[f[0]].push_back({f[1], f[2]});
        priority_queue<tuple<int,int,int>, vector<tuple<int,int,int>>, greater<>> pq;
        pq.push({0, src, K + 1});
        vector<int> bestStops(n, -1);
        while (!pq.empty()) {
            auto [cost, u, stops] = pq.top(); pq.pop();
            if (u == dst) return cost;
            if (stops <= 0 || stops <= bestStops[u]) continue;
            bestStops[u] = stops;
            for (auto& [v, w] : adj[u]) pq.push({cost + w, v, stops - 1});
        }
        return -1;
    }
};

import heapq
class Solution:
    def findCheapestPrice(self, n, flights, src, dst, K):
        adj = [[] for _ in range(n)]
        for u, v, w in flights:
            adj[u].append((v, w))
        pq = [(0, src, K + 1)]
        best_stops = [-1] * n
        while pq:
            cost, u, stops = heapq.heappop(pq)
            if u == dst:
                return cost
            if stops <= 0 or stops <= best_stops[u]:
                continue
            best_stops[u] = stops
            for v, w in adj[u]:
                heapq.heappush(pq, (cost + w, v, stops - 1))
        return -1

class Solution {
public:
    int swimInWater(vector<vector<int>>& g) {
        int n = g.size();
        vector<vector<int>> best(n, vector<int>(n, INT_MAX));
        priority_queue<tuple<int,int,int>, vector<tuple<int,int,int>>, greater<>> pq;
        pq.push({g[0][0], 0, 0}); best[0][0] = g[0][0];
        int dx[] = {0,0,1,-1}, dy[] = {1,-1,0,0};
        while (!pq.empty()) {
            auto [t, r, c] = pq.top(); pq.pop();
            if (r == n - 1 && c == n - 1) return t;
            if (t > best[r][c]) continue;
            for (int d = 0; d < 4; d++) {
                int nr = r + dx[d], nc = c + dy[d];
                if (nr < 0 || nc < 0 || nr >= n || nc >= n) continue;
                int nt = max(t, g[nr][nc]);
                if (nt < best[nr][nc]) { best[nr][nc] = nt; pq.push({nt, nr, nc}); }
            }
        }
        return -1;
    }
};

import heapq
class Solution:
    def swimInWater(self, g):
        n = len(g)
        best = [[float('inf')] * n for _ in range(n)]
        best[0][0] = g[0][0]
        pq = [(g[0][0], 0, 0)]
        while pq:
            t, r, c = heapq.heappop(pq)
            if r == n - 1 and c == n - 1:
                return t
            if t > best[r][c]:
                continue
            for nr, nc in ((r,c+1),(r,c-1),(r+1,c),(r-1,c)):
                if 0 <= nr < n and 0 <= nc < n:
                    nt = max(t, g[nr][nc])
                    if nt < best[nr][nc]:
                        best[nr][nc] = nt
                        heapq.heappush(pq, (nt, nr, nc))
        return -1

class Solution {
public:
    int countPaths(int n, vector<vector<int>>& roads) {
        const long long MOD = 1e9 + 7;
        vector<vector<pair<int,long long>>> adj(n);
        for (auto& r : roads) { adj[r[0]].push_back({r[1], r[2]}); adj[r[1]].push_back({r[0], r[2]}); }
        vector<long long> dist(n, LLONG_MAX), ways(n, 0);
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
        dist[0] = 0; ways[0] = 1; pq.push({0, 0});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[u]) continue;
            for (auto& [v, w] : adj[u]) {
                if (d + w < dist[v]) { dist[v] = d + w; ways[v] = ways[u]; pq.push({dist[v], v}); }
                else if (d + w == dist[v]) ways[v] = (ways[v] + ways[u]) % MOD;
            }
        }
        return (int)ways[n - 1];
    }
};

import heapq
class Solution:
    def countPaths(self, n, roads):
        MOD = 10**9 + 7
        adj = [[] for _ in range(n)]
        for u, v, w in roads:
            adj[u].append((v, w)); adj[v].append((u, w))
        dist = [float('inf')] * n
        ways = [0] * n
        dist[0], ways[0] = 0, 1
        pq = [(0, 0)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                if d + w < dist[v]:
                    dist[v] = d + w
                    ways[v] = ways[u]
                    heapq.heappush(pq, (dist[v], v))
                elif d + w == dist[v]:
                    ways[v] = (ways[v] + ways[u]) % MOD
        return ways[n - 1] % MOD
